"use strict";(globalThis.webpackChunkmy_website=globalThis.webpackChunkmy_website||[]).push([[5931],{719(e,t,o){o.r(t),o.d(t,{assets:()=>h,contentTitle:()=>r,default:()=>d,frontMatter:()=>a,metadata:()=>i,toc:()=>l});const i=JSON.parse('{"id":"stoicism/epictetus/discourses/book-3/index","title":"Discourses \u2014 Book 3","description":"Book 3","source":"@site/docs/stoicism/epictetus/discourses/book-3/index.md","sourceDirName":"stoicism/epictetus/discourses/book-3","slug":"/stoicism/epictetus/discourses/book-3/","permalink":"/justinus/docs/stoicism/epictetus/discourses/book-3/","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":1,"frontMatter":{"title":"Discourses \u2014 Book 3","sidebar_position":1},"sidebar":"philosophersSidebar","previous":{"title":"Book 2, Ch. 26","permalink":"/justinus/docs/stoicism/epictetus/discourses/book-2/discourses-book-2-chapter-26"},"next":{"title":"Book 3, Ch. 1","permalink":"/justinus/docs/stoicism/epictetus/discourses/book-3/discourses-book-3-chapter-1"}}');var s=o(4848),n=o(8453);const a={title:"Discourses \u2014 Book 3",sidebar_position:1},r="Discourses",h={},l=[{value:"Book 3",id:"book-3",level:2},{value:"Sonnet 4.6 Summary",id:"sonnet-46-summary",level:2}];function c(e){const t={em:"em",h1:"h1",h2:"h2",header:"header",p:"p",strong:"strong",...(0,n.R)(),...e.components},{Details:o}=t;return o||function(e,t){throw new Error("Expected "+(t?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("Details",!0),(0,s.jsxs)(s.Fragment,{children:[(0,s.jsxs)("div",{style:{textAlign:"center"},children:[(0,s.jsx)(t.header,{children:(0,s.jsx)(t.h1,{id:"discourses",children:"Discourses"})}),(0,s.jsx)(t.h2,{id:"book-3",children:"Book 3"})]}),"\n",(0,s.jsx)(t.p,{children:(0,s.jsx)(t.em,{children:"Translated by P.E. Matheson (Oxford: Clarendon Press, 1916)"})}),"\n",(0,s.jsxs)(o,{open:!0,children:[(0,s.jsx)("summary",{children:"Sonnet 4.6 Summary"}),(0,s.jsx)(t.h2,{id:"sonnet-46-summary",children:"Sonnet 4.6 Summary"}),(0,s.jsx)(t.p,{children:"If Book 1 builds the framework and Book 2 diagnoses the gap between knowing and living, Book 3 is where Epictetus becomes most demanding about what genuine philosophical practice actually requires. The tone throughout is less patient than the earlier books \u2014 more direct about who is and isn't doing the work, more willing to send people away if they're not ready, more specific about what readiness actually looks like."}),(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"The body and its adornments"})," open the book pointedly (Ch. 1) and the theme of misidentification \u2014 confusing yourself with your physical form \u2014 runs underneath much of what follows. You are a rational will. Everything else is material. Adorning the body instead of the governing principle is not merely vanity; it is a fundamental mistake about what you are. The three-department structure from Ch. 2 \u2014 will, impulse, assent, in that order \u2014 provides the organizing logic for what training should address, and Epictetus returns to it repeatedly to insist that most people skip the essential first department entirely and busy themselves with the third."]}),(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Training is the book's central practical concern"})," in a way it wasn't quite in earlier books. Chapters 3, 8, 10, 12, and 18 all address the question of how to practice \u2014 not what to believe but how to build the habits that make belief operational. The daily drill of classifying impressions (Ch. 3 and 8), the principle of going in the opposite direction from your natural inclinations (Ch. 12), the insistence that illness and hardship are themselves training opportunities rather than interruptions of it (Chs. 5 and 10) \u2014 these form a coherent practical curriculum. The recurring image is athletic: you train in advance precisely so that when the crisis comes, the response is automatic rather than deliberate. You don't think your way through a fever; you bear it as you've practiced bearing things."]}),(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"The danger of social contamination"})," receives explicit treatment (Ch. 16) that is more cautionary than anything in the earlier books. While a student's principles are still in \"wax form,\" proximity to the untrained is genuinely dangerous because their convictions, however wrong, are real convictions, while the student's fine words are still just words. The burning coal and the cold coal: one of them changes state. Until your principles are fixed, the odds favor the wrong outcome. This is why philosophers have always recommended leaving familiar environments \u2014 old habits and old company prevent the formation of new ones."]}),(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"The Cynic chapter (Ch. 22)"})," stands apart from everything else in Book 3 as a sustained portrait of what complete philosophical commitment would look like in its most demanding form. The Cynic is a divine messenger, a living argument, a scout who reports back to humanity on the true nature of good and evil. The prerequisites are extraordinary \u2014 no entanglements, no vulnerabilities, genuine mastery of every passion, a body and bearing that prove the teaching without words. Most people who inquire about the Cynic life are looking for a socially acceptable form of laziness. The real thing is almost impossibly rare and demands what amounts to a divine calling. The chapter functions as a kind of limit-case: here is what full commitment would require. Measure yourself against it honestly."]}),(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"The performing philosopher"})," is Book 3's version of Book 2's half-philosopher \u2014 the person who has substituted display for practice. Chapters 21 and 23 are among Epictetus's most sustained attacks on this figure. Teaching before you've digested what you've learned is like vomiting on your students. Lecturing for applause is the precise opposite of what a philosopher's school is for \u2014 you should leave it in pain, having been shown what is actually wrong with you, not in pleasure, carrying away your shoulder and your ulcer exactly as you brought them. Rufus's standard: if you find leisure to praise me, my words were wasted. Socrates never invited anyone; he was sought out because people knew they would be helped and confronted, not entertained."]}),(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Separation, loss, and the fear of want"})," dominate the book's emotional register in its final chapters. Chapter 24's treatment of attachment \u2014 loving without gripping, being fully present without making the other person a hostage to your peace of mind \u2014 is among the most psychologically nuanced passages in the Discourses. The distinction between Caesar's peace (external, covering wars and bandits) and philosophy's peace (internal, covering grief, love, fever, and envy) captures what is actually being offered. Chapter 26 then faces the fear of poverty and death head-on: the only thing genuinely worthy of confidence is the will. Everything else \u2014 body, property, comfort, reputation \u2014 is on loan, returnable on demand. When the general signals retreat, you follow without complaint."]}),(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"The book's emotional arc"})," moves from the corrective (adorn the right thing, train in the right order, avoid the wrong company) through the demanding (the Cynic standard, the teacher's responsibility) to something approaching the consolatory. The final chapters have a warmth that the earlier ones don't \u2014 Epictetus describes how he would wish to die (in care of his will, praising God), addresses the fear of starvation with a combination of bracing practicality and genuine tenderness, and closes with the reminder that fear of death, not death itself, is the root of all servility. Remove that fear and everything else becomes manageable. That is what all the training, all the lectures, and all the exercises are finally for."]})]})]})}function d(e={}){const{wrapper:t}={...(0,n.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(c,{...e})}):c(e)}},8453(e,t,o){o.d(t,{R:()=>a,x:()=>r});var i=o(6540);const s={},n=i.createContext(s);function a(e){const t=i.useContext(n);return i.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:a(e.components),i.createElement(n.Provider,{value:t},e.children)}}}]);